namespace {
using CK_BYTE=unsigned char; using CK_BBOOL=CK_BYTE; using CK_ULONG=unsigned long; using CK_RV=CK_ULONG; using CK_SLOT_ID=CK_ULONG; using CK_SESSION_HANDLE=CK_ULONG; using CK_OBJECT_HANDLE=CK_ULONG; using CK_OBJECT_CLASS=CK_ULONG; using CK_KEY_TYPE=CK_ULONG; using CK_USER_TYPE=CK_ULONG; using CK_FLAGS=CK_ULONG; using CK_MECHANISM_TYPE=CK_ULONG; using CK_VOID_PTR=void*; using CK_BYTE_PTR=CK_BYTE*; using CK_ULONG_PTR=CK_ULONG*; using CK_SLOT_ID_PTR=CK_SLOT_ID*; using CK_SESSION_HANDLE_PTR=CK_SESSION_HANDLE*; using CK_OBJECT_HANDLE_PTR=CK_OBJECT_HANDLE*;
struct CK_VERSION{CK_BYTE major;CK_BYTE minor;}; struct CK_ATTRIBUTE{CK_ULONG type;CK_VOID_PTR pValue;CK_ULONG ulValueLen;}; struct CK_MECHANISM{CK_MECHANISM_TYPE mechanism;CK_VOID_PTR pParameter;CK_ULONG ulParameterLen;};
using FnInitialize=CK_RV(*)(CK_VOID_PTR); using FnFinalize=CK_RV(*)(CK_VOID_PTR); using FnGetSlotList=CK_RV(*)(CK_BBOOL,CK_SLOT_ID_PTR,CK_ULONG_PTR); using FnOpenSession=CK_RV(*)(CK_SLOT_ID,CK_FLAGS,CK_VOID_PTR,CK_VOID_PTR,CK_SESSION_HANDLE_PTR); using FnCloseSession=CK_RV(*)(CK_SESSION_HANDLE); using FnLogin=CK_RV(*)(CK_SESSION_HANDLE,CK_USER_TYPE,CK_BYTE_PTR,CK_ULONG); using FnLogout=CK_RV(*)(CK_SESSION_HANDLE); using FnFindObjectsInit=CK_RV(*)(CK_SESSION_HANDLE,CK_ATTRIBUTE*,CK_ULONG); using FnFindObjects=CK_RV(*)(CK_SESSION_HANDLE,CK_OBJECT_HANDLE_PTR,CK_ULONG,CK_ULONG_PTR); using FnFindObjectsFinal=CK_RV(*)(CK_SESSION_HANDLE); using FnGetAttributeValue=CK_RV(*)(CK_SESSION_HANDLE,CK_OBJECT_HANDLE,CK_ATTRIBUTE*,CK_ULONG); using FnSignInit=CK_RV(*)(CK_SESSION_HANDLE,CK_MECHANISM*,CK_OBJECT_HANDLE); using FnSign=CK_RV(*)(CK_SESSION_HANDLE,CK_BYTE_PTR,CK_ULONG,CK_BYTE_PTR,CK_ULONG_PTR);
struct CK_FUNCTION_LIST{
 CK_VERSION version;FnInitialize C_Initialize;FnFinalize C_Finalize;void* C_GetInfo;void* C_GetFunctionList;FnGetSlotList C_GetSlotList;void* C_GetSlotInfo;void* C_GetTokenInfo;void* C_GetMechanismList;void* C_GetMechanismInfo;void* C_InitToken;void* C_InitPIN;void* C_SetPIN;FnOpenSession C_OpenSession;FnCloseSession C_CloseSession;void* C_CloseAllSessions;void* C_GetSessionInfo;void* C_GetOperationState;void* C_SetOperationState;FnLogin C_Login;FnLogout C_Logout;void* C_CreateObject;void* C_CopyObject;void* C_DestroyObject;void* C_GetObjectSize;FnGetAttributeValue C_GetAttributeValue;void* C_SetAttributeValue;FnFindObjectsInit C_FindObjectsInit;FnFindObjects C_FindObjects;FnFindObjectsFinal C_FindObjectsFinal;void* C_EncryptInit;void* C_Encrypt;void* C_EncryptUpdate;void* C_EncryptFinal;void* C_DecryptInit;void* C_Decrypt;void* C_DecryptUpdate;void* C_DecryptFinal;void* C_DigestInit;void* C_Digest;void* C_DigestUpdate;void* C_DigestKey;void* C_DigestFinal;FnSignInit C_SignInit;FnSign C_Sign;
};
using FnGetFunctionList=CK_RV(*)(CK_FUNCTION_LIST**);
constexpr CK_RV CKR_OK=0,CKR_CRYPTOKI_ALREADY_INITIALIZED=0x191,CKR_USER_ALREADY_LOGGED_IN=0x100; constexpr CK_FLAGS CKF_SERIAL_SESSION=0x4; constexpr CK_USER_TYPE CKU_USER=1; constexpr CK_OBJECT_CLASS CKO_PUBLIC_KEY=2,CKO_PRIVATE_KEY=3; constexpr CK_KEY_TYPE CKK_EC=3; constexpr CK_ULONG CKA_CLASS=0x00000000,CKA_KEY_TYPE=0x00000100,CKA_ID=0x00000102,CKA_EC_PARAMS=0x00000180,CKA_EC_POINT=0x00000181; constexpr CK_MECHANISM_TYPE CKM_ECDSA=0x00001041;
[[noreturn]] void fail(const std::string&m){throw std::runtime_error(m);} void check(const char*op,CK_RV rv){if(rv!=CKR_OK){std::ostringstream o;o<<op<<" failed: 0x"<<std::hex<<rv;fail(o.str());}}
std::string jsonEscape(const std::string&s){std::ostringstream o;for(unsigned char c:s){switch(c){case '"':o<<"\\\"";break;case '\\':o<<"\\\\";break;case '\n':o<<"\\n";break;case '\r':o<<"\\r";break;case '\t':o<<"\\t";break;default:if(c<0x20)o<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<int(c);else o<<c;}}return o.str();}
std::string b64url(const unsigned char*d,size_t n){static constexpr char t[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";std::string o;o.reserve((n*4+2)/3);for(size_t i=0;i<n;i+=3){unsigned v=unsigned(d[i])<<16;if(i+1<n)v|=unsigned(d[i+1])<<8;if(i+2<n)v|=d[i+2];o.push_back(t[(v>>18)&63]);o.push_back(t[(v>>12)&63]);if(i+1<n)o.push_back(t[(v>>6)&63]);if(i+2<n)o.push_back(t[v&63]);}return o;}
std::vector<unsigned char> hexDecode(const std::string&s){if(s.empty()||s.size()%2)fail("invalid hex");auto nib=[](char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return-1;};std::vector<unsigned char> o(s.size()/2);for(size_t i=0;i<o.size();++i){int a=nib(s[2*i]),b=nib(s[2*i+1]);if(a<0||b<0)fail("invalid hex");o[i]=static_cast<unsigned char>((a<<4)|b);}return o;}
std::map<std::string,std::string> parseRef(const std::string&r){if(r.empty()||r.size()>4000)fail("invalid provider key ref");std::map<std::string,std::string> o;size_t start=0;while(start<r.size()){size_t end=r.find('|',start);if(end==std::string::npos)end=r.size();std::string p=r.substr(start,end-start);size_t eq=p.find('=');if(eq==std::string::npos||eq==0||eq+1>=p.size())fail("invalid provider key ref field");if(!o.emplace(p.substr(0,eq),p.substr(eq+1)).second)fail("duplicate provider key ref field");start=end+1;}for(auto k:{"module","slot","id","pinfile"})if(!o.count(k))fail(std::string("provider key ref missing ")+k);if(o.size()!=4)fail("provider key ref contains unsupported field");return o;}
unsigned long parseSlot(const std::string&s){char*e=nullptr;errno=0;auto v=std::strtoul(s.c_str(),&e,10);if(errno||!e||*e)fail("invalid PKCS11 slot");return v;}
void assertRegularAbsolute(const std::string&p,const char*what,bool secret=false){if(p.empty()||p[0]!='/')fail(std::string(what)+" absolute path required");struct stat st{};if(lstat(p.c_str(),&st)!=0)fail(std::string(what)+" unavailable");if(S_ISLNK(st.st_mode)||!S_ISREG(st.st_mode))fail(std::string(what)+" must be a regular non-symlink file");if(secret){if((st.st_mode&077)!=0)fail(std::string(what)+" permissions must deny group/other access");auto uid=geteuid();if(st.st_uid!=uid&&st.st_uid!=0)fail(std::string(what)+" owner mismatch");}}
std::string readPin(const std::string&p){assertRegularAbsolute(p,"PKCS11 PIN file",true);std::ifstream f(p,std::ios::binary);if(!f)fail("PKCS11 PIN file unreadable");std::string s((std::istreambuf_iterator<char>(f)),{});if(s.size()>1024)fail("PKCS11 PIN too large");while(!s.empty()&&(s.back()=='\n'||s.back()=='\r'))s.pop_back();if(s.empty())fail("PKCS11 PIN empty");return s;}
struct Module{void*h{};CK_FUNCTION_LIST*f{};bool initialized=false;explicit Module(const std::string&p){assertRegularAbsolute(p,"PKCS11 module");h=dlopen(p.c_str(),RTLD_NOW|RTLD_LOCAL);if(!h)fail(std::string("PKCS11 module load failed: ")+dlerror());auto get=reinterpret_cast<FnGetFunctionList>(dlsym(h,"C_GetFunctionList"));if(!get)fail("PKCS11 module missing C_GetFunctionList");check("C_GetFunctionList",get(&f));if(!f||!f->C_Initialize||!f->C_Finalize||!f->C_GetSlotList||!f->C_OpenSession||!f->C_CloseSession||!f->C_Login||!f->C_Logout||!f->C_FindObjectsInit||!f->C_FindObjects||!f->C_FindObjectsFinal||!f->C_GetAttributeValue||!f->C_SignInit||!f->C_Sign)fail("PKCS11 function table incomplete");auto rv=f->C_Initialize(nullptr);if(rv!=CKR_OK&&rv!=CKR_CRYPTOKI_ALREADY_INITIALIZED)check("C_Initialize",rv);initialized=rv==CKR_OK;}~Module(){if(h){if(initialized&&f)f->C_Finalize(nullptr);dlclose(h);}}};
struct Session{Module&m;CK_SESSION_HANDLE h{};bool logged=false;Session(Module&mod,CK_SLOT_ID slot,const std::string&pin):m(mod){CK_ULONG count=0;check("C_GetSlotList(size)",m.f->C_GetSlotList(1,nullptr,&count));if(count==0)fail("PKCS11 token unavailable");std::vector<CK_SLOT_ID> slots(count);check("C_GetSlotList",m.f->C_GetSlotList(1,slots.data(),&count));slots.resize(count);if(std::find(slots.begin(),slots.end(),slot)==slots.end())fail("PKCS11 configured slot has no present token");check("C_OpenSession",m.f->C_OpenSession(slot,CKF_SERIAL_SESSION,nullptr,nullptr,&h));auto rv=m.f->C_Login(h,CKU_USER,reinterpret_cast<CK_BYTE_PTR>(const_cast<char*>(pin.data())),pin.size());if(rv!=CKR_OK&&rv!=CKR_USER_ALREADY_LOGGED_IN)check("C_Login",rv);logged=rv==CKR_OK;}~Session(){if(h){if(logged)m.f->C_Logout(h);m.f->C_CloseSession(h);}}};
CK_OBJECT_HANDLE findUnique(Module&m,CK_SESSION_HANDLE s,CK_OBJECT_CLASS klass,const std::vector<unsigned char>&id){CK_KEY_TYPE kt=CKK_EC;CK_ATTRIBUTE q[]={{CKA_CLASS,&klass,sizeof(klass)},{CKA_KEY_TYPE,&kt,sizeof(kt)},{CKA_ID,const_cast<unsigned char*>(id.data()),id.size()}};check("C_FindObjectsInit",m.f->C_FindObjectsInit(s,q,3));CK_OBJECT_HANDLE objects[2]{};CK_ULONG n=0;auto rv=m.f->C_FindObjects(s,objects,2,&n),end=m.f->C_FindObjectsFinal(s);check("C_FindObjects",rv);check("C_FindObjectsFinal",end);if(n!=1)fail(n?"PKCS11 key id is ambiguous":"PKCS11 key id not found");return objects[0];}
std::vector<unsigned char> attribute(Module&m,CK_SESSION_HANDLE s,CK_OBJECT_HANDLE o,CK_ULONG type){CK_ATTRIBUTE a{type,nullptr,0};check("C_GetAttributeValue(size)",m.f->C_GetAttributeValue(s,o,&a,1));if(a.ulValueLen==~CK_ULONG(0)||a.ulValueLen==0||a.ulValueLen>4096)fail("PKCS11 attribute unavailable or oversized");std::vector<unsigned char> v(a.ulValueLen);a.pValue=v.data();check("C_GetAttributeValue",m.f->C_GetAttributeValue(s,o,&a,1));v.resize(a.ulValueLen);return v;}
std::vector<unsigned char> unwrapPoint(const std::vector<unsigned char>&v){if(v.size()==65&&v[0]==0x04)return v;if(v.size()<2||v[0]!=0x04)fail("PKCS11 EC point is not DER OCTET STRING");size_t i=1,len=0;if(v[i]<0x80)len=v[i++];else{size_t n=v[i++]&0x7f;if(n==0||n>2||i+n>v.size())fail("PKCS11 EC point DER length invalid");for(size_t j=0;j<n;++j)len=(len<<8)|v[i++];}if(i+len!=v.size()||len!=65||v[i]!=0x04)fail("PKCS11 EC point is not uncompressed P-256");return {v.begin()+static_cast<long>(i),v.end()};}
std::string describe(Module&m,CK_SESSION_HANDLE s,const std::vector<unsigned char>&id){CK_OBJECT_HANDLE pub=findUnique(m,s,CKO_PUBLIC_KEY,id);std::vector<unsigned char> params=attribute(m,s,pub,CKA_EC_PARAMS);static const unsigned char p256[]={0x06,0x08,0x2a,0x86,0x48,0xce,0x3d,0x03,0x01,0x07};if(params.size()!=sizeof(p256)||!std::equal(params.begin(),params.end(),p256))fail("PKCS11 key is not P-256");auto p=unwrapPoint(attribute(m,s,pub,CKA_EC_POINT));return "{\"kty\":\"EC\",\"crv\":\"P-256\",\"x\":\""+b64url(p.data()+1,32)+"\",\"y\":\""+b64url(p.data()+33,32)+"\"}";}
struct Opened{std::map<std::string,std::string> ref;Module module;Session session;std::vector<unsigned char> id;Opened(const std::string&r):ref(parseRef(r)),module(ref.at("module")),session(module,parseSlot(ref.at("slot")),readPin(ref.at("pinfile"))),id(hexDecode(ref.at("id"))){if(id.empty()||id.size()>64)fail("PKCS11 key id size invalid");}};
int probe(){const char*r=std::getenv("CIEAV_PKCS11_PROBE_REF");if(!r||!*r){std::cout<<"{\"protocol\":\"CIEAV_KEY_PROVIDER_V1\",\"provider\":\"TPM\",\"nativeProvider\":\"PKCS11\",\"available\":false,\"hardwareBacked\":false,\"reason\":\"CIEAV_PKCS11_PROBE_REF not configured\"}\n";return 20;}try{Opened o(r);(void)describe(o.module,o.session.h,o.id);std::cout<<"{\"protocol\":\"CIEAV_KEY_PROVIDER_V1\",\"provider\":\"TPM\",\"nativeProvider\":\"PKCS11\",\"available\":true,\"hardwareBacked\":false,\"attestationRequired\":true}\n";return 0;}catch(const std::exception&e){std::cout<<"{\"protocol\":\"CIEAV_KEY_PROVIDER_V1\",\"provider\":\"TPM\",\"nativeProvider\":\"PKCS11\",\"available\":false,\"hardwareBacked\":false,\"reason\":\""<<jsonEscape(e.what())<<"\"}\n";return 20;}}
}
int main(int argc,char**argv){try{if(argc<2){std::cerr<<"usage: cieav-linux-pkcs11 <probe|describe|sign-es256> ...\n";return 2;}std::string cmd=argv[1];if(cmd=="probe")return probe();if(cmd=="describe"&&argc==3){Opened o(argv[2]);auto jwk=describe(o.module,o.session.h,o.id);std::cout<<"{\"protocol\":\"CIEAV_KEY_PROVIDER_V1\",\"operation\":\"describe\",\"provider\":\"TPM\",\"algorithm\":\"ES256\",\"keyName\":\""<<jsonEscape(argv[2])<<"\",\"hardwareBacked\":false,\"attestationRequired\":true,\"publicJwk\":"<<jwk<<"}\n";return 0;}if(cmd=="sign-es256"&&argc==4){auto d=hexDecode(argv[3]);if(d.size()!=32)fail("sign-es256 requires a 32-byte SHA-256 digest");Opened o(argv[2]);(void)describe(o.module,o.session.h,o.id);auto key=findUnique(o.module,o.session.h,CKO_PRIVATE_KEY,o.id);CK_MECHANISM mech{CKM_ECDSA,nullptr,0};check("C_SignInit",o.module.f->C_SignInit(o.session.h,&mech,key));CK_ULONG n=0;check("C_Sign(size)",o.module.f->C_Sign(o.session.h,d.data(),d.size(),nullptr,&n));if(n!=64)fail("PKCS11 CKM_ECDSA signature is not 64-byte P-256 raw form");std::vector<unsigned char> sig(n);check("C_Sign",o.module.f->C_Sign(o.session.h,d.data(),d.size(),sig.data(),&n));sig.resize(n);std::cout<<"{\"protocol\":\"CIEAV_KEY_PROVIDER_V1\",\"operation\":\"sign-es256\",\"provider\":\"TPM\",\"keyName\":\""<<jsonEscape(argv[2])<<"\",\"signatureEncoding\":\"IEEE-P1363\",\"signature\":\""<<b64url(sig.data(),sig.size())<<"\"}\n";return 0;}throw std::runtime_error("invalid command or arguments");}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 20;}}
